using Endgame.Domain.Tree;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Endgame.Infrastructure.Persistence.Configurations;

internal static class TreeNodeMapping
{
    /// <summary>The columns every level shares. Ids are generated by the domain, never by the database.</summary>
    public static void MapNode<T>(this EntityTypeBuilder<T> builder, string table)
        where T : TreeNode
    {
        builder.ToTable(table);
        builder.HasKey(n => n.Id);
        builder.Property(n => n.Id).HasColumnName("id").ValueGeneratedNever();
        builder.Property(n => n.Name).HasColumnName("name").HasMaxLength(TreeNode.MaxNameLength).IsRequired();
        builder.Property(n => n.Slug).HasColumnName("slug").HasMaxLength(SlugRules.MaxLength).IsRequired();
        builder.Property(n => n.CreatedAt).HasColumnName("created_at").IsRequired();
    }
}
